begin;
select pg_advisory_xact_lock(2028,1100);
do $seed$
declare item jsonb; cid uuid; cname text; items jsonb := $data$[{"seed_key": "career-company-01", "name": "Money Forward", "industry": "IT / FinTech / SaaS", "tags": ["Product", "Business", "AI", "Software", "FinTech"], "url": "https://recruit.moneyforward.com/students/", "aliases": ["マネーフォワード"]}, {"seed_key": "career-company-02", "name": "SmartHR", "industry": "IT / SaaS", "tags": ["Product", "Business", "SaaS", "Software", "ML"], "url": "https://recruit.smarthr.co.jp/newgrads/", "aliases": ["スマートHR"]}, {"seed_key": "career-company-03", "name": "Sansan", "industry": "IT / SaaS", "tags": ["Product", "Business", "SaaS", "Software", "AI"], "url": "https://jp.corp-sansan.com/recruit/newgrads/", "aliases": ["サンサン"]}, {"seed_key": "career-company-04", "name": "CyberAgent", "industry": "IT / Media / Advertising", "tags": ["Business", "Product", "AI", "Software", "Media", "Advertising"], "url": "https://www.cyberagent.co.jp/careers/students/", "aliases": ["サイバーエージェント"]}, {"seed_key": "career-company-05", "name": "PKSHA Technology", "industry": "AI / Software", "tags": ["AI", "ML", "Software", "Business", "Product"], "url": "https://www.pkshatech.com/recruitment/", "aliases": ["PKSHA", "パークシャ"]}, {"seed_key": "career-company-06", "name": "DeNA", "industry": "IT / Internet", "tags": ["Product", "Business", "Software", "AI"], "url": "https://student.dena.com/", "aliases": ["ディー・エヌ・エー"]}, {"seed_key": "career-company-07", "name": "Mercari", "industry": "IT / Marketplace", "tags": ["Product", "Business", "Software", "Global"], "url": "https://careers.mercari.com/new-graduates/", "aliases": ["メルカリ"]}, {"seed_key": "career-company-08", "name": "Rakuten Group", "industry": "IT / EC / FinTech", "tags": ["Product", "Business", "Software", "FinTech", "Global"], "url": "https://global.rakuten.com/corp/careers/graduates/", "aliases": ["楽天グループ", "楽天"]}, {"seed_key": "career-company-09", "name": "LINE Yahoo", "industry": "IT / Internet", "tags": ["Product", "Product Planner", "Business",