y": "IT / Cloud / EC", "tags": ["Software", "Product", "Cloud", "Business"], "url": "https://www.amazon.jobs/content/en/career-programs/student-programs", "aliases": ["アマゾンジャパン", "アマゾン"]}, {"seed_key": "career-company-28", "name": "Preferred Networks", "industry": "AI / Robotics", "tags": ["AI", "ML", "Robotics", "Research", "Software"], "url": "https://www.preferred.jp/ja/careers/", "aliases": ["プリファードネットワークス", "PFN"]}, {"seed_key": "career-company-29", "name": "GMO Internet Group", "industry": "IT / Infrastructure", "tags": ["Software", "AI", "Security", "Infrastructure", "Business"], "url": "https://internet.gmo/recruit/rookies/", "aliases": ["GMOインターネットグループ"]}, {"seed_key": "career-company-30", "name": "Works Applications", "industry": "Enterprise Software", "tags": ["Software", "Product", "SaaS"], "url": "https://www.worksap.co.jp/recruit/", "aliases": ["ワークスアプリケーションズ"]}, {"seed_key": "career-company-31", "name": "SCSK", "industry": "IT / SI", "tags": ["Software", "DX", "AI", "Business"], "url": "https://www.scsk.jp/recruit/saiyo/", "aliases": ["SCSK"]}, {"seed_key": "career-company-32", "name": "ITOCHU Techno-Solutions", "industry": "IT / SI", "tags": ["Cloud", "AI", "Software", "Business", "Trading"], "url": "https://www.ctc-g.co.jp/recruit/newgrads/", "aliases": ["伊藤忠テクノソリューションズ", "CTC"]}, {"seed_key": "career-company-33", "name": "NS Solutions", "industry": "IT / SI", "tags": ["Software", "AI", "DX"], "url": "https://www.nssol.nipponsteel.com/recruit/", "aliases": ["日鉄ソリューションズ", "NSSOL"]}, {"seed_key": "career-company-34", "name": "NTT COMWARE", "industry": "IT / Telecom", "tags": ["Software", "Cloud", "AI", "Telecom"], "url": "https://www.nttcom.co.jp/employ/recruit/", "aliases": ["NTTコムウェア"]}, {"seed_key": "career-company-35", "name": "Mitsubishi Electric Digital Innovation", "industry": "IT / DX", "tags": ["DX", "AI", "Software", "Security"], "url": "https://www.mitsubishielectric.co.jp/medigital/recruit/", "aliases": ["三菱電機デジタルイノベーション"]}, {"seed_key": "career-company-36", "name": "Olympus", "industry": "Medical Devices", "tags": ["Medical", "Product", "Digital", "Software", "AI"], "url": "https://www.olympus.co.jp/recruit/newgraduates/", "aliases": ["オリンパス"]}, {"seed_key": "career-company-37", "name": "Terumo", "industry": "Medical Devices", "tags": ["Medical", "DX", "Product", "Business", "Data"], "url": "https://recruit.terumo.co.jp/", "aliases": ["テルモ"]}, {"seed_key": "career-company-38", "name": "OMRON", "industry": "Electronics / Healthcare", "tags": ["Healthcare", "AI", "DX", "Product", "Automation"], "url": "https://www.omron.com/jp/ja/recruit/newgraduate/", "aliases": ["オムロン"]}, {"seed_key": "career-company-39", "name": "MUFG Bank", "industry": "Banking / Financial", "tags": ["Finance", "Digital", "Product", "Business", "Global"], "url": "https://www.saiyo.bk.mufg.jp/", "aliases": ["三菱UFJ銀行", "MUFG"]}, {"seed_key": "career-company-40", "name": "SMBC", "industry": "Banking / Financial", "tags": ["Finance", "Digital", "Business", "Product"], "url": "https://www.smbc.co.jp/recruit/", "aliases": ["三井住友銀行"]}, {"seed_key": "career-company-41", "name": "Mizuho Financial Group", "industry": "Financial", "tags": ["Finance", "Digital", "Product", "Business"], "url": "https://www.mizuho-fg.co.jp/saiyou/", "aliases": ["みずほフィナンシャルグループ", "みずほ銀行", "Mizuho"]}, {"seed_key": "career-company-42", "name": "Sumitomo Mitsui Trust Bank", "industry": "Trust Bank / Financial", "tags": ["Finance", "Digital", "Business", "IT"], "url": "https://www.smtb.jp/recruit/new-graduate/", "aliases": ["三井住友信託銀行"]}, {"seed_key": "career-company-43", "name": "Mitsubishi Corporation", "industry": "General Trading Company", "tags": ["Trading", "Business Development", "Investment", "Global", "DX"], "url": "https://www.career-mc.com/newgraduate/", "aliases": ["三菱商事"]}, {"seed_key": "career-company-44", "name": "Mitsui & Co.", "industry": "General Trading Company", "tags": ["Trading", "Investment", "Business Development", "Global", "DX"], "url": "https://career.mitsui.com/", "aliases": ["三井物産"]}, {"seed_key": "career-company-45", "name": "ITOCHU Corporation", "industry": "General Trading Company", "tags": ["Trading", "Business", "Investment", "Global", "DX"], "url": "https://career.itochu.co.jp/student/", "aliases": ["伊藤忠商事", "ITOCHU"]}, {"seed_key": "career-company-46", "name": "Sumitomo Corporation", "industry": "General Trading Company", "tags": ["Trading", "Business Development", "Investment", "DX", "Global"], "url": "https://sumitomocorp-recruiting.com/", "aliases": ["住友商事"]}, {"seed_key": "career-company-47", "name": "Marubeni", "industry": "General Trading Company", "tags": ["Trading", "Business", "Investment", "AI", "DX", "Global"], "url": "https://www.marubeni-recruit.com/", "aliases": ["丸紅"]}, {"seed_key": "career-company-48", "name": "Toyota Tsusho", "industry": "Trading / Mobility", "tags": ["Trading", "Mobility", "Business", "Investment", "DX"], "url": "https://www.toyota-tsusho-recruit.com/", "aliases": ["豊田通商"]}, {"seed_key": "career-company-49", "name": "Dentsu", "industry": "Advertising / Marketing", "tags": ["Marketing", "Business", "DX", "Product", "Creative"], "url": "https://www.dentsu.co.jp/careers/", "aliases": ["電通"]}, {"seed_key": "career-company-50", "name": "SB C&S", "industry": "IT Trading", "tags": ["Trading", "IT", "Business", "Cloud", "AI", "Product"], "url": "https://recruit.cas.softbank.jp/newgrad/", "aliases": ["SB C&S"]}]$data$;
begin
 for item in select * from jsonb_array_elements(items) loop
  select id,name into cid,cname from public.companies where seed_key=item->>'seed_key' or name=item->>'name' or name in (select jsonb_array_elements_text(item->'aliases')) order by (seed_key=item->>'seed_key') desc nulls last, (name=item->>'name') desc limit 1;
  if cid is null then
   insert into public.companies(name,industry,website,tags,aliases,seed_key)
   values(item->>'name',item->>'industry',item->>'url',array(select jsonb_array_elements_text(item->'tags')),array(select jsonb_array_elements_text(item->'aliases')),item->>'seed_key')
   on conflict(name) do nothing returning id,name into cid,cname;
   if cid is null then select id,name into cid,cname from public.companies where name=item->>'name'; end if;
  end if;
  -- Only missing seed metadata is added to an existing master; names/industries/URLs stay intact.
  update public.companies set tags=case when cardinality(tags)=0 then array(select jsonb_array_elements_text(item->'tags')) else tags end, seed_key=coalesce(seed_key,item->>'seed_key'), aliases=array(select distinct x from unnest(aliases || array(select jsonb_array_elements_text(item->'aliases')) || array[item->>'name']) x) where id=cid;
  if not exists(select 1 from public.recruitment_templates where company_id=cid and graduation_year=2028 and public and url ~* '^https?://[^/ ]+') then
   insert into public.recruitment_templates(company_id,company_name,graduation_year,job_category,position_name,selection_type,url,source_url,source_type,verification_status,application_status,application_start,application_deadline,last_verified_at,notes_public,public,seed_key)
   values(cid,cname,2028,'','2028卒 採用情報','未発表',item->>'url',item->>'url','official','unverified','unknown',null,null,null,'募集監視用。2028卒の職種・日程・選考フローは未確認です。公式サイトで確認してください。',true,'watch-2028-'||(item->>'seed_key'))
   on conflict(seed_key) do nothing;
  end if;
 end loop;
 if (select count(*) from public.companies where seed_key in (select value->>'seed_key' from jsonb_array_elements(items))) <> 50 then raise exception 'Expected all 50 companies'; end if;
end $seed$;
select count(*) as seeded_companies from public.companies where seed_key like 'career-company-%';
select count(distinct c.id) as companies_with_public_2028_templates from public.companies c join public.recruitment_templates t on t.company_id=c.id where c.seed_key like 'career-company-%' and t.graduation_year=2028 and t.public;
commit;
